### Test File
Create `test/session/impulse-resolution-validation.test.ts`:

```typescript
import { describe, test, expect, beforeEach, afterEach } from "bun:test"
import { ImpulseResolver } from "../../src/session/impulse-resolver"
import { Impulse } from "../../src/session/impulse"
import * as fs from "fs/promises"
import * as path from "path"

describe("Impulse Resolution Validation", () => {
  const testDir = "/tmp/impulse-test-" + Date.now()

  beforeEach(async () => {
    await fs.mkdir(testDir, { recursive: true })
  })

  afterEach(async () => {
    await fs.rm(testDir, { recursive: true, force: true })
  })

  test("resolves file impulse with offset and limit", async () => {
    // Create test file
    const testFile = path.join(testDir, "test.ts")
    const content = Array.from({ length: 100 }, (_, i) => 
      `function test${i}() { return ${i} }`
    ).join("\n")
    await fs.writeFile(testFile, content)

    // Create file impulse
    const impulse: Impulse = {
      id: "test-file",
      type: "file",
      pointer: {
        type: "file",
        path: testFile,
        offset: 10,
        limit: 20
      },
      budget: 1000,
      priority: "high",
      loaded: false
    }

    // Resolve
    const content = await ImpulseResolver.resolve(impulse.pointer)

    // Validate
    expect(content).toContain("function test10")
    expect(content).toContain("function test29")
    expect(content).not.toContain("function test9")
    expect(content).not.toContain("function test30")
  })

  test("resolves memo impulse", async () => {
    const impulse: Impulse = {
      id: "test-memo",
      type: "memo",
      pointer: {
        type: "memo",
        content: "This is a test memo with context"
      },
      budget: 500,
      priority: "medium",
      loaded: false
    }

    const content = await ImpulseResolver.resolve(impulse.pointer)
    expect(content).toBe("This is a test memo with context")
  })

  test("resolves component impulse", async () => {
    // Create test file with function
    const testFile = path.join(testDir, "component.ts")
    await fs.writeFile(testFile, `
function authenticateUser(user: string, pass: string) {
  // Authentication logic
  return true
}

function logoutUser() {
  // Logout logic
}
    `)

    const impulse: Impulse = {
      id: "test-component",
      type: "component",
      pointer: {
        type: "component",
        file: testFile,
        component: "authenticateUser"
      },
      budget: 1000,
      priority: "high",
      loaded: false
    }

    const content = await ImpulseResolver.resolve(impulse.pointer)
    expect(content).toContain("authenticateUser")
    expect(content).toContain("Authentication logic")
  })

  test("resolves bashOutput impulse", async () => {
    const impulse: Impulse = {
      id: "test-bash",
      type: "bashOutput",
      pointer: {
        type: "bashOutput",
        command: "echo 'test output'"
      },
      budget: 500,
      priority: "medium",
      loaded: false
    }

    const content = await ImpulseResolver.resolve(impulse.pointer)
    expect(content).toContain("test output")
  })

  test("resolves commit impulse", async () => {
    // This test requires a git repo - skip if not available
    try {
      const impulse: Impulse = {
        id: "test-commit",
        type: "commit",
        pointer: {
          type: "commit",
          hash: "HEAD"
        },
        budget: 2000,
        priority: "medium",
        loaded: false
      }

      const content = await ImpulseResolver.resolve(impulse.pointer)
      expect(content).toBeTruthy()
      expect(content.length).toBeGreaterThan(0)
    } catch (e) {
      console.log("Skipping commit test (not in git repo)")
    }
  })

  test("enforces budget limits", async () => {
    // Create large file
    const testFile = path.join(testDir, "large.ts")
    const largeContent = Array.from({ length: 1000 }, (_, i) => 
      `function large${i}() { return ${i} }`
    ).join("\n")
    await fs.writeFile(testFile, largeContent)

    const impulse: Impulse = {
      id: "test-budget",
      type: "file",
      pointer: {
        type: "file",
        path: testFile
      },
      budget: 500,  // Small budget
      priority: "medium",
      loaded: false
    }

    // Load with budget enforcement
    await ImpulseResolver.load(impulse)

    // Should be truncated to fit budget
    expect(impulse.loaded).toBe(true)
    expect(impulse.tokenCount).toBeLessThanOrEqual(impulse.budget)
    expect(impulse.truncated).toBe(true)
  })

  test("tracks usage statistics", async () => {
    const impulse: Impulse = {
      id: "test-usage",
      type: "memo",
      pointer: {
        type: "memo",
        content: "Test content"
      },
      budget: 500,
      priority: "medium",
      loaded: false,
      usageStats: {
        loadCount: 0,
        totalCost: 0,
        lastAccessedAt: 0
      }
    }

    // Load multiple times
    await ImpulseResolver.load(impulse)
    await ImpulseResolver.load(impulse)
    await ImpulseResolver.load(impulse)

    expect(impulse.usageStats.loadCount).toBe(3)
    expect(impulse.usageStats.lastAccessedAt).toBeGreaterThan(0)
  })
})

console.log("✅ All impulse resolution tests created")
```

