# Task: Test Memory Agent

## Your Task
Test that the memory agent automatically prepares context before agent turns.

### Test Approach
1. Trigger memory agent with different intents
2. Verify impulses created
3. Check priority assignment
4. Validate budget management

### Test File
Create `test/session/memory-agent-validation.test.ts`:

```typescript
import { describe, test, expect } from "bun:test"
import { MemoryAgent } from "../../src/session/memory-agent"
import { SessionMemory } from "../../src/session/memory"

describe("Memory Agent Validation", () => {
  test("analyzes intent and creates impulses", async () => {
    const memory = new SessionMemory("test-session")
    const agent = new MemoryAgent(memory)

    // Simulate user intent
    const intent = "Fix the authentication bug in src/auth.ts"

    // Memory agent should:
    // 1. Classify intent as "code_fix"
    // 2. Create impulses for relevant files
    // 3. Prioritize based on relevance
    const impulses = await agent.prepareContext(intent)

    expect(impulses.length).toBeGreaterThan(0)
    expect(impulses.some(i => i.type === "file")).toBe(true)
    expect(impulses.some(i => i.priority === "high")).toBe(true)
  })

  test("respects budget limits", async () => {
    const memory = new SessionMemory("test-session")
    const agent = new MemoryAgent(memory, {
      maxTokens: 5000  // Budget limit
    })

    const intent = "Implement a large feature with many files"
    const impulses = await agent.prepareContext(intent)

    // Calculate total tokens
    let totalTokens = 0
    for (const impulse of impulses) {
      if (impulse.loaded) {
        totalTokens += impulse.tokenCount || 0
      }
    }

    // Should not exceed budget
    expect(totalTokens).toBeLessThanOrEqual(5000)
  })

  test("loads high-priority impulses first", async () => {
    const memory = new SessionMemory("test-session")
    const agent = new MemoryAgent(memory, {
      maxTokens: 3000  // Limited budget
    })

    // Create multiple impulses with different priorities
    await memory.createImpulse({
      id: "low-priority",
      type: "memo",
      pointer: { type: "memo", content: "Low priority content" },
      priority: "low",
      budget: 1000
    })

    await memory.createImpulse({
      id: "high-priority",
      type: "memo",
      pointer: { type: "memo", content: "High priority content" },
      priority: "high",
      budget: 1000
    })

    await memory.createImpulse({
      id: "medium-priority",
      type: "memo",
      pointer: { type: "memo", content: "Medium priority content" },
      priority: "medium",
      budget: 1000
    })

    // Load with budget
    await agent.loadImpulses()

    // High priority should be loaded first
    const highPriority = memory.getImpulse("high-priority")
    expect(highPriority?.loaded).toBe(true)

    // Low priority might not be loaded due to budget
    const lowPriority = memory.getImpulse("low-priority")
    // May or may not be loaded depending on budget
  })
})

console.log("✅ Memory agent tests created")
```

