# Task: Test Ephemeral Agent Specialization

## Your Task
Verify that activity templates create ephemeral agents with task-specific instructions.

### Test Approach
1. Execute activity with multiple tasks
2. Inspect prompts sent to LLM
3. Verify impulse context injected
4. Confirm different tasks have different instructions

### Validation Script
Create `validate-ephemeral-agents.ts`:

```typescript
import { ActivityTemplate } from "./src/session/activity-template"
import { TemplateExecutor } from "./src/session/template-executor"

// Create test template with 2 different tasks
const template: ActivityTemplate.Template = {
  id: "test-ephemeral",
  name: "Test Ephemeral Agents",
  category: "infrastructure",
  version: { major: 1, minor: 0, patch: 0 },
  tasks: [
    {
      id: "task-1",
      subagent: "activity",
      description: "First task - authentication specialist",
      dependencies: [],
      prompt: {
        template: `# You are an authentication specialist

## Task
Implement JWT authentication using: {{authPattern}}

## Requirements
- Use bcrypt for passwords
- Follow security best practices`,
        maxTokens: 5000,
        compressionStrategy: "filter",
        variables: [
          {
            name: "authPattern",
            type: "string",
            required: true,
            description: "Auth pattern to follow"
          }
        ]
      },
      validation: { commands: [] },
      retry: { maxAttempts: 1, strategy: "simple" }
    },
    {
      id: "task-2",
      subagent: "activity",
      description: "Second task - testing specialist",
      dependencies: ["task-1"],
      prompt: {
        template: `# You are a testing specialist

## Task
Write comprehensive tests for the authentication system.

## Requirements
- Test success and failure cases
- Cover edge cases
- Follow testing conventions`,
        maxTokens: 5000,
        compressionStrategy: "filter",
        variables: []
      },
      validation: { commands: [] },
      retry: { maxAttempts: 1, strategy: "simple" }
    }
  ]
}

// Execute and capture prompts
async function validateEphemeralAgents() {
  console.log("\n=== Validating Ephemeral Agent Specialization ===")

  const executor = new TemplateExecutor()
  const prompts: string[] = []

  // Hook into prompt building
  const originalBuildPrompt = executor.buildPromptForTask
  executor.buildPromptForTask = async (task, variables) => {
    const prompt = await originalBuildPrompt.call(executor, task, variables)
    prompts.push(prompt)
    return prompt
  }

  // Execute template
  await executor.execute(template, {
    authPattern: "JWT with refresh tokens"
  })

  // Validate
  console.log(`\n✅ Captured ${prompts.length} prompts`)

  // Task 1 should be auth specialist
  expect(prompts[0]).toContain("authentication specialist")
  expect(prompts[0]).toContain("JWT authentication")
  expect(prompts[0]).toContain("bcrypt")

  // Task 2 should be testing specialist (different!)
  expect(prompts[1]).toContain("testing specialist")
  expect(prompts[1]).toContain("comprehensive tests")
  expect(prompts[1]).not.toContain("authentication specialist")

  console.log("\n✅ Ephemeral Agents Validated:")
  console.log("   - Task 1: Auth specialist")
  console.log("   - Task 2: Testing specialist")
  console.log("   - Different instructions per task")
  console.log("   - Same base agent, different specialization")

  return {
    passed: true,
    promptsCaptured: prompts.length,
    specializationsVerified: true
  }
}

validateEphemeralAgents()
  .then(result => console.log("\nResult:", result))
  .catch(err => console.error("Error:", err))
```

### Run Validation
```bash
cd {{opencodePath}}
bun run validate-ephemeral-agents.ts
```

