- Impulse context injected in prompts
- Variables interpolated correctly
- Same base agent, different specialization per task

# Task: Test Cross-Task Impulse Sharing (Pattern 5)

## Your Task
Verify that task outputs can be shared as impulses to subsequent tasks.

### Test Template
Create activity that demonstrates:
1. Task 1 creates output
2. Task 2 receives Task 1 output as impulse
3. Verify impulse content matches Task 1 output

### Validation Script
Create `validate-impulse-sharing.ts`:

```typescript
import { ActivityTemplate } from "./src/session/activity-template"
import { TemplateExecutor } from "./src/session/template-executor"

async function validateImpulseSharing() {
  console.log("\n=== Validating Cross-Task Impulse Sharing ===")

  const template: ActivityTemplate.Template = {
    id: "test-sharing",
    name: "Test Impulse Sharing",
    category: "infrastructure",
    version: { major: 1, minor: 0, patch: 0 },
    tasks: [
      {
        id: "analyze",
        subagent: "activity",
        description: "Analyze and produce output",
        dependencies: [],
        prompt: {
          template: `Analyze the requirement and output structured JSON:
{
  "analysis": "Requirement needs X, Y, Z",
  "components": ["ComponentA", "ComponentB"],
  "estimate": "3 hours"
}`,
          maxTokens: 3000,
          compressionStrategy: "filter",
          variables: []
        },
        validation: { 
          requiredPatterns: ["\"analysis\":", "\"components\":"],
          commands: []
        },
        retry: { maxAttempts: 1, strategy: "simple" }
      },
      {
        id: "implement",
        subagent: "activity",
        description: "Implement based on analysis",
        dependencies: ["analyze"],
        impulseReferences: ["analyzeOutput"],
        prompt: {
          template: `# Task: Implement Feature

## Analysis Results (Pattern 5: Cross-Task Impulse)
{{analyzeOutput}}

**Analysis metadata**:
- Tokens: {{analyzeOutput.tokens}}
- Type: {{analyzeOutput.type}}

## Your Task
Implement the components identified in the analysis:
- Components: {{analyzeOutput.content.components}}
- Estimate: {{analyzeOutput.content.estimate}}

Create implementation based on analysis.`,
          maxTokens: 5000,
          compressionStrategy: "filter",
          variables: [
            {
              name: "analyzeOutput",
              type: "string",
              required: true,
              description: "Output from analyze task"
            }
          ]
        },
        validation: { commands: [] },
        retry: { maxAttempts: 1, strategy: "simple" }
      }
    ]
  }

  // Execute with impulse sharing
  const executor = new TemplateExecutor()
  const activity = await executor.execute(template, {})

  // Verify task 2 received task 1 output
  const task2Session = activity.tasks.find(t => t.id === "implement")
  const task2Impulses = task2Session?.impulses || []

  expect(task2Impulses.length).toBeGreaterThan(0)
  expect(task2Impulses.some(i => i.id === "analyzeOutput")).toBe(true)

  console.log("\n✅ Cross-Task Impulse Sharing Validated")
  console.log("   - Task 1 output captured")
  console.log("   - Task 2 received Task 1 output as impulse")
  console.log("   - Impulse content accessible in Task 2 prompt")

  return {
    passed: true,
    impulsesShared: task2Impulses.length,
    crossTaskSharingWorks: true
  }
}

validateImpulseSharing()
  .then(result => console.log("\nResult:", result))
  .catch(err => console.error("Error:", err))
```

### Run Validation
```bash
cd {{opencodePath}}
bun run validate-impulse-sharing.ts
```

